package cn.pawday;

import cn.pawday.identity.Crypto;
import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import java.net.URI;
import java.net.http.*;
import java.nio.file.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class V312FulfillmentIntegrationTests {
 static final EmbeddedPostgres PG;
 static {try{PG=EmbeddedPostgres.builder().setPort(0).start();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->PG.getJdbcUrl("postgres","postgres"));r.add("spring.datasource.username",()->"postgres");r.add("spring.datasource.password",()->"postgres");r.add("pawday.auth.secret-key",()->"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=");for(String k:List.of("management.health.redis.enabled","management.health.rabbit.enabled","pawday.outbox.workers-enabled","pawday.outbox.consumer-enabled","pawday.search.enabled","pawday.storage.cleanup-enabled","pawday.checkout.expiry-enabled","pawday.ordering.expiry-enabled","pawday.payment.recovery-enabled","pawday.refund.recovery-enabled","pawday.settlement.worker-enabled"))r.add(k,()->false);r.add("pawday.booking.simulation-enabled",()->true);}
 @Autowired JdbcTemplate db;@Autowired Crypto crypto;@Autowired Clock clock;@LocalServerPort int port;
 final JsonMapper json=JsonMapper.builder().build();final HttpClient http=HttpClient.newHttpClient();
 static final List<Map<String,Object>> SAMPLES=new CopyOnWriteArrayList<>();
 UUID store,merchantId;String merchant,reader,user,other,foreign;
 record Response(int status,JsonNode body){JsonNode data(){return body.get("data");}String id(){return data().get("id").asString();}}
 String key(){return UUID.randomUUID().toString();}
 String identity(boolean consumer,UUID m,UUID st,List<String> permissions){UUID p=UUID.randomUUID(),role=UUID.randomUUID();String realm=consumer?"CONSUMER":"MERCHANT";
  if(consumer){UUID u=UUID.randomUUID();db.update("INSERT INTO app_user(id,status) VALUES (?,'ACTIVE')",u);db.update("INSERT INTO identity_principal(id,realm,user_id) VALUES (?,'CONSUMER',?)",p,u);}else db.update("INSERT INTO identity_principal(id,realm,merchant_id,login_name,password_hash) VALUES (?,'MERCHANT',?,?,?)",p,m,key(),"TEST-ONLY");
  db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,?,?,'BOOKING TEST')",role,realm,key());for(String code:permissions)db.update("INSERT INTO role_permission SELECT ?,id FROM permission WHERE code=?",role,code);db.update("INSERT INTO principal_role VALUES (?,?,?)",p,role,realm);
  if(!consumer)db.update("INSERT INTO principal_store_scope VALUES (?,?,?)",p,m,st);
  String token=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'BOOKING-IT',?,?,?)",UUID.randomUUID(),p,crypto.hash(token),Timestamp.from(clock.instant().plusSeconds(900)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));return token;
 }
 UUID store(UUID m){UUID s=UUID.randomUUID();db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST booking store')",s,m);db.update("INSERT INTO nearby_store_profile(store_id,city,category,address,phone,business_hours,longitude,latitude,services,publication_status,claim_status) VALUES (?,'TEST','GROOMING','TEST address','123456','TEST hours',106,29,'[\"GROOMING\"]','PUBLISHED','VERIFIED')",s);return s;}
 @BeforeEach void setup(){merchantId=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST booking merchant','ACTIVE')",merchantId);store=store(merchantId);merchant=identity(false,merchantId,store,List.of("store.read","store.nearby.write"));reader=identity(false,merchantId,store,List.of("store.read"));user=identity(true,null,null,List.of());other=identity(true,null,null,List.of());UUID m=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST foreign','ACTIVE')",m);foreign=identity(false,m,store(m),List.of("store.read","store.nearby.write"));}
 Response req(String method,String path,Object body,String token,Map<String,String> headers){try{var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(30));if(token!=null)builder.header("Authorization","Bearer "+token);headers.forEach(builder::header);builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));if(body!=null)builder.header("Content-Type","application/json");var response=http.send(builder.build(),HttpResponse.BodyHandlers.ofString());var result=json.readTree(response.body());SAMPLES.add(Map.of("method",method.toLowerCase(),"path",path,"status",response.statusCode(),"response",result));return new Response(response.statusCode(),result);}catch(Exception e){throw new AssertionError(e);}}
 Response get(String path,String token){return req("GET",path,null,token,Map.of());}
 Response post(String path,Object b,String token){return req("POST",path,b,token,Map.of("Idempotency-Key",key()));}
 String services(){return "/merchant/stores/"+store+"/booking-services";}
 String create(){var r=post(services(),Map.of("title","TEST wash","kind","GROOMING"),merchant);assertEquals(200,r.status(),r.body().toString());return r.id();}
 Map<String,Object> interval(int seats){Instant start=clock.instant().plus(Duration.ofDays(2)).truncatedTo(java.time.temporal.ChronoUnit.SECONDS);return Map.of("starts_at",start.toString(),"ends_at",start.plusSeconds(3600).toString(),"capacity",seats);}
 String slot(String service,int seats){var r=post("/merchant/booking-services/"+service+"/slots",interval(seats),merchant);assertEquals(200,r.status(),r.body().toString());return r.id();}
 Response reserve(String slot,String who,String k){return req("POST","/consumer/service-bookings",Map.of("slot_id",slot),who,Map.of("Idempotency-Key",k));}
 Response cancel(String booking,String who,String k,long v){return req("POST","/consumer/service-bookings/"+booking+"/cancel",Map.of(),who,Map.of("Idempotency-Key",k,"If-Match","\""+v+"\""));}
 Response state(String service,String status,long v){return req("PUT","/merchant/booking-services/"+service+"/state",Map.of("status",status),merchant,Map.of("Idempotency-Key",key(),"If-Match","\""+v+"\""));}

 String seed(long startSeconds,long endSeconds){String service=create();UUID slot=UUID.randomUUID(),booking=UUID.randomUUID();Instant now=clock.instant();
  db.update("INSERT INTO booking_slots(id,service_id,starts_at,ends_at,capacity) VALUES (?,?,?,?,1)",slot,UUID.fromString(service),Timestamp.from(now.plusSeconds(startSeconds)),Timestamp.from(now.plusSeconds(endSeconds)));
  UUID uid=db.queryForObject("SELECT p.user_id FROM identity_principal p JOIN auth_session a ON a.principal_id=p.id WHERE a.access_token_hash=?",UUID.class,crypto.hash(user));
  db.update("INSERT INTO service_bookings(id,slot_id,service_id,store_id,user_id,service_title) VALUES (?,?,?,?,?,'TEST fulfillment')",booking,slot,UUID.fromString(service),store,uid);return booking.toString();
 }
 String path(String id){return "/merchant/stores/"+store+"/service-bookings/"+id+"/fulfillment";}
 String token(String id){var r=get("/consumer/service-bookings/"+id+"/credential",user);assertEquals(200,r.status(),r.body().toString());return r.data().get("credential").asString();}
 Response fulfill(String id,String status,String token,String reason,long version,String key,String who){return req("POST",path(id),Map.of("status",status,"credential",token,"reason_code",reason),who,Map.of("Idempotency-Key",key,"If-Match","\""+version+"\""));}
 Response fulfill(String id,String status,String token,String reason,long version){return fulfill(id,status,token,reason,version,key(),merchant);}
 @AfterAll static void samples()throws Exception{Path p=Path.of("target/v312-contract-samples.json");Files.createDirectories(p.getParent());Files.writeString(p,JsonMapper.builder().build().writeValueAsString(SAMPLES));}
 @Test void oneTimeCredentialArrivalDepartureAndDurableHistory(){String id=seed(-60,3600),t=token(id),k=key();var arrival=fulfill(id,"CHECKED_IN",t,"",0,k,merchant);assertEquals(200,arrival.status(),arrival.body().toString());assertEquals(1,arrival.data().get("version").asInt());assertEquals(arrival.data(),fulfill(id,"CHECKED_IN",t,"",0,k,merchant).data());assertEquals(409,fulfill(id,"CHECKED_IN",t,"",1).status());assertEquals(409,get("/consumer/service-bookings/"+id+"/credential",user).status());assertEquals(409,cancel(id,user,key(),0).status());assertEquals(200,fulfill(id,"COMPLETED","","",1).status());assertEquals(409,fulfill(id,"EXCEPTION","","CUSTOMER_DISPUTE",2).status());var history=get("/consumer/service-bookings/"+id+"/fulfillment",user);assertEquals(200,history.status());assertEquals(2,history.data().size());assertFalse(history.body().toString().contains("actor_id"));assertFalse(history.body().toString().contains(t));assertEquals(2,get(path(id),merchant).data().size());var own=get("/consumer/service-bookings",user);assertEquals("COMPLETED",own.data().get(0).get("status").asString());assertEquals(0,db.queryForObject("SELECT count(*) FROM payments",Integer.class));assertEquals("BOOKED",db.queryForObject("SELECT status FROM service_bookings WHERE id=?",String.class,UUID.fromString(id)));}
 @Test void credentialWindowExpiryAndBookingBinding(){String early=seed(7200,10800),t=token(early);assertEquals(409,fulfill(early,"CHECKED_IN",t,"",0).status());String active=seed(-60,3600);assertEquals(409,fulfill(active,"CHECKED_IN",t,"",0).status());assertEquals(400,fulfill(active,"CHECKED_IN","short","",0).status());String expired=seed(-7200,-3600);assertEquals(409,get("/consumer/service-bookings/"+expired+"/credential",user).status());assertEquals(409,fulfill(expired,"CHECKED_IN",t,"",0).status());assertEquals(409,fulfill(active,"COMPLETED","","",0).status());String upcoming=seed(600,3600);assertEquals(200,fulfill(upcoming,"CHECKED_IN",token(upcoming),"",0).status());assertEquals(409,fulfill(upcoming,"COMPLETED","","",1).status());}
 @Test void noShowAndExceptionAreExplicitImmutableTerminalFacts(){String past=seed(-7200,-3600);assertEquals(200,fulfill(past,"NO_SHOW","","",0).status());assertEquals(409,fulfill(past,"EXCEPTION","","SAFETY_STOP",1).status());String active=seed(-60,3600);assertEquals(409,fulfill(active,"NO_SHOW","","",0).status());assertEquals(200,fulfill(active,"EXCEPTION","","CUSTOMER_DISPUTE",0).status());assertEquals(409,fulfill(active,"CHECKED_IN",token(seed(-60,3600)),"",1).status());String checked=seed(-60,3600);assertEquals(200,fulfill(checked,"CHECKED_IN",token(checked),"",0).status());assertEquals(200,fulfill(checked,"EXCEPTION","","SAFETY_STOP",1).status());String before=seed(7200,10800);assertEquals(409,fulfill(before,"EXCEPTION","","SERVICE_UNAVAILABLE",0).status());}
 @Test void permissionsOwnershipRevocationAndCredentialPrivacy(){String id=seed(-60,3600),t=token(id);assertEquals(401,get("/consumer/service-bookings/"+id+"/credential",null).status());assertEquals(404,get("/consumer/service-bookings/"+id+"/credential",other).status());assertEquals(403,get("/consumer/service-bookings/"+id+"/credential",merchant).status());assertEquals(404,get("/consumer/service-bookings/"+id+"/fulfillment",other).status());assertEquals(404,get(path(id),foreign).status());assertEquals(403,fulfill(id,"CHECKED_IN",t,"",0,key(),reader).status());assertEquals(403,fulfill(id,"CHECKED_IN",t,"",0,key(),user).status());assertEquals(200,get(path(id),reader).status());var staff=get("/merchant/stores/"+store+"/service-bookings",merchant);assertFalse(staff.body().toString().contains(t));assertFalse(staff.body().toString().contains("credential"));String k=key();assertEquals(200,fulfill(id,"CHECKED_IN",t,"",0,k,merchant).status());db.update("DELETE FROM principal_store_scope WHERE store_id=? AND principal_id IN (SELECT principal_id FROM auth_session WHERE access_token_hash=?)",store,crypto.hash(merchant));assertEquals(404,fulfill(id,"CHECKED_IN",t,"",0,k,merchant).status());}
 @Test void idempotencyVersionsInvalidFieldsAndPaging(){String id=seed(-60,3600),t=token(id),k=key();assertEquals(409,fulfill(id,"CHECKED_IN",t,"",99).status());assertEquals(400,fulfill(id,"EXCEPTION","","arbitrary PII",0).status());assertEquals(400,fulfill(id,"COMPLETED",t,"",0).status());assertEquals(400,req("POST",path(id),Map.of("status","CHECKED_IN","credential",t,"reason_code","","extra",1),merchant,Map.of("Idempotency-Key",key(),"If-Match","\"0\"")).status());assertEquals(200,fulfill(id,"CHECKED_IN",t,"",0,k,merchant).status());assertEquals(409,fulfill(id,"COMPLETED","","",1,k,merchant).status());assertEquals(200,fulfill(id,"COMPLETED","","",1).status());var first=get(path(id)+"?limit=1",merchant);assertTrue(first.body().get("page").get("has_more").asBoolean());assertEquals(1,get(path(id)+"?limit=1&cursor="+first.body().get("page").get("next_cursor").asString(),merchant).data().size());assertEquals(400,get(path(id)+"?limit=101",merchant).status());}
 @Test void concurrentArrivalAndCancellationProduceOnlyOneOutcome()throws Exception{String id=seed(600,3600),t=token(id);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var latch=new CountDownLatch(1);var a=pool.submit(()->{latch.await();return fulfill(id,"CHECKED_IN",t,"",0);});var b=pool.submit(()->{latch.await();return cancel(id,user,key(),0);});latch.countDown();var statuses=new ArrayList<>(List.of(a.get().status(),b.get().status()));Collections.sort(statuses);assertEquals(List.of(200,409),statuses);}assertEquals(1,db.queryForObject("SELECT (SELECT count(*) FROM booking_fulfillment_events WHERE booking_id=?)+(SELECT count(*) FROM service_bookings WHERE id=? AND status='CANCELLED')",Integer.class,UUID.fromString(id),UUID.fromString(id)));}
 @Test void sameKeyConcurrentArrivalReplaysOneFact()throws Exception{String id=seed(-60,3600),t=token(id),k=key();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var a=pool.submit(()->fulfill(id,"CHECKED_IN",t,"",0,k,merchant));var b=pool.submit(()->fulfill(id,"CHECKED_IN",t,"",0,k,merchant));assertEquals(200,a.get().status());assertEquals(200,b.get().status());}assertEquals(1,db.queryForObject("SELECT count(*) FROM booking_fulfillment_events WHERE booking_id=?",Integer.class,UUID.fromString(id)));}
 @Test void databaseRejectsMutationTruncationAndInvalidTransition(){String id=seed(-60,3600);UUID bid=UUID.fromString(id);UUID actor=db.queryForObject("SELECT principal_id FROM auth_session WHERE access_token_hash=?",UUID.class,crypto.hash(merchant));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("INSERT INTO booking_fulfillment_events VALUES (?,?,1,'COMPLETED','',?,?)",UUID.randomUUID(),bid,actor,Timestamp.from(clock.instant())));assertEquals(200,fulfill(id,"CHECKED_IN",token(id),"",0).status());for(String sql:List.of("UPDATE booking_fulfillment_events SET reason_code='SAFETY_STOP'","DELETE FROM booking_fulfillment_events","TRUNCATE booking_fulfillment_events","UPDATE service_bookings SET status='CANCELLED',version=version+1,cancelled_at=now(),cancelled_by='"+actor+"' WHERE id='"+id+"'"))assertThrows(org.springframework.dao.DataAccessException.class,()->db.execute(sql));assertEquals(1,db.queryForObject("SELECT count(*) FROM booking_fulfillment_events WHERE booking_id=?",Integer.class,bid));}
}
